_ANSI_RE = re.compile(r'\033\[[^m]*m')

def _rl(s: str) -> str:
    """readline 向けに ANSI コードを \001...\002 で囲み幅ゼロと認識させる。"""
    return _ANSI_RE.sub(r'\001\g<0>\002', s)
